INSERT INTO "dynasty_groups" ("id","name","alt_names","scope","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","note") VALUES ('sanguo','三国','[]','cn',220,1,NULL,'year',280,12,NULL,'month',2640,3371,'220–280年三国（曹魏、蜀汉、孙吴）；狭义自曹丕代汉至晋灭吴。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('shu','蜀汉','["汉","蜀","季汉"]',NULL,NULL,'cn','east_asia',219,1,NULL,'year',263,12,NULL,'month',2628,3167,'ochre',NULL,'sanguo','219年刘备取得汉中后，群臣推戴为汉中王并上表汉帝，建立王国官属。221年刘备在成都称帝，国号汉，后世称蜀汉或季汉，以益州为核心、成都为都，立国主张承续汉统。刘备死后刘禅在位，诸葛亮等主持政务并多次北伐；蜀汉长期与曹魏交战，263年魏军入蜀、刘禅投降，王朝结束。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('wei','曹魏','["魏"]',NULL,NULL,'cn','east_asia',213,6,16,'day',266,2,NULL,'month',2561,3193,'ochre',NULL,'sanguo','213年曹操受汉献帝封为魏公，216年进爵魏王，220年曹丕继承魏王。220年曹丕受汉献帝禅让称帝，国号魏，史称曹魏；以洛阳为都，主要统治中国北方，与蜀汉、孙吴长期对峙。曹氏历经曹丕、曹叡及曹芳、曹髦、曹奂五帝；高平陵之变后司马氏掌握朝政，266年曹奂禅位于司马炎，曹魏为西晋取代。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('wu','孙吴','["吴"]',NULL,NULL,'cn','east_asia',221,9,23,'day',280,5,NULL,'month',2660,3364,'ochre',NULL,'sanguo','孙坚、孙策先后经营江东，孙权于200年继承其势力。221年受魏封为吴王，222年改元黄武、与魏决裂，形成独立吴政权；229年称帝，同年从武昌迁都建业。孙亮、孙休、孙皓相继继位，280年孙皓降晋，吴亡。');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cao-cao','曹操','wei','[]',NULL,NULL,155,1,NULL,'year',220,3,15,'day','["君主","政治家","军事家","文学家"]','曹嵩之子。东汉末起兵讨董卓，192年领兖州，196年迎汉献帝至许县，官渡之战击败袁绍后逐步控制北方，208年任汉丞相。213年受封魏公，建立魏国社稷、宗庙及官属，216年进爵魏王；220年去世，曹丕继承魏王并于同年称帝，追尊其为武皇帝。生前未称帝，亦以诗文与军事著述传世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹操"},{"label":"《三国志·魏书·武帝纪》（维基文库）","url":"https://zh.wikisource.org/wiki/三國志/卷01"},{"label":"《三国志·魏书·武帝纪》","url":"https://zh.wikisource.org/zh-hans/三國志/卷01"},{"label":"《后汉书·献帝纪》","url":"https://zh.wikisource.org/zh-hans/後漢書/卷9"},{"label":"建安纪年农历对照表","url":"https://zh.wikipedia.org/wiki/建安_(东汉)"},{"label":"河北省文物考古研究院：曹操营建的邺城","url":"https://www.hbswwkg.com/2023-12/12/content_9113769.html"}]','武王,武皇帝','太祖',NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cao-pi','曹丕','wei','[]',NULL,NULL,187,1,NULL,'year',226,6,NULL,'month','["皇帝"]','曹操之子，217年被立为魏王太子。曹操自196年迎汉献帝至许县后掌握汉廷，逐步控制北方，并受封魏公、魏王；曹丕于220年继承丞相与魏王职位，继而受汉献帝禅让称帝，建立魏。推行九品中正制，并与吴、蜀交战；226年去世，曹叡继位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹丕"},{"label":"《三国志·魏书·文帝纪》","url":"https://zh.wikisource.org/zh-hans/三國志/卷02"},{"label":"《后汉书·献帝纪》","url":"https://zh.wikisource.org/zh-hans/後漢書/卷9"},{"label":"河北省文物考古研究院：曹操营建的邺城","url":"https://www.hbswwkg.com/2023-12/12/content_9113769.html"}]','文皇帝','高祖','魏文帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('cao-rui','曹叡','wei','[]',NULL,NULL,206,1,NULL,'year',239,1,NULL,'year','["皇帝"]','曹丕之子，226—239年在位，是曹魏第二帝。即位后面对蜀汉、孙吴的持续攻势，主持防御与政务；因无亲生子，临终托孤并立养子曹芳为帝，由曹爽、司马懿辅政。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/曹叡"}]','明皇帝','烈祖','魏明帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('deng-ai','邓艾','wei','[]',NULL,NULL,197,1,NULL,'year',264,1,NULL,'year','["军事家","将领"]','曹魏将领，景元四年率军由阴平道奇袭江油，参与灭蜀之战；钟会诬告邓艾谋反并将其囚禁，钟会兵变失败后邓艾在押送途中被杀。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/邓艾"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-bei','刘备','shu','[]',NULL,NULL,161,1,NULL,'year',223,6,NULL,'month','["皇帝"]','涿郡人，自称汉中山靖王后裔。184年募兵参与镇压黄巾，后辗转依附公孙瓒、曹操、袁绍和刘表等势力。208年与孙权联合抗曹，赤壁战后取得荆州部分地区；214年夺取刘璋的益州，219年据汉中并称汉中王。曹丕代汉后，刘备于221年在成都称帝，国号汉；伐吴败于夷陵，223年病逝。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘备"},{"label":"《三国志·蜀书·先主传》","url":"https://zh.wikisource.org/zh-hans/三國志/卷32"},{"label":"《后汉书·献帝纪》","url":"https://zh.wikisource.org/zh-hans/後漢書/卷9"},{"label":"建安纪年农历对照表","url":"https://zh.wikipedia.org/wiki/建安_(东汉)"},{"label":"刘备称汉中王日期考证（历表冲突）","url":"https://en.wikipedia.org/wiki/Liu_Bei#Notes"}]','昭烈皇帝','烈祖','昭烈帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-shan','刘禅','shu','[]',NULL,NULL,207,1,NULL,'year',271,1,NULL,'year','["皇帝"]','刘备之子，223年继位，在位至263年，是蜀汉第二帝。刘备去世后由诸葛亮辅政，诸葛亮及其后蒋琬、费祎、姜维等先后主持国政；263年魏军攻入蜀地，刘禅向邓艾投降，蜀汉灭亡。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘禅"}]','孝怀皇帝',NULL,'蜀汉后主','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('liu-zhang','刘璋','shu','[]',NULL,NULL,176,1,NULL,'year',219,1,NULL,'year','["军阀"]','益州牧，刘焉之子；引刘备入蜀后失益州，东汉末地方势力；投降后被刘备迁往公安并封振威将军；刘备接管益州后建立蜀汉政权。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/刘璋"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('sun-quan','孙权','wu','[]',NULL,NULL,182,7,NULL,'month',252,5,NULL,'month','["皇帝"]','孙坚之子、孙策之弟，200年孙策遇刺后继掌江东。208年联合刘备在赤壁击败曹操，219年夺取关羽所据荆州，扩大长江中下游的统治区域。221年受魏封为吴王，222年与魏决裂、建立独立的吴政权；229年称帝，国号吴，同年由武昌迁都建业。晚年储位之争引发宫廷冲突，252年去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/孙权"},{"label":"《三国志·魏书·文帝纪》","url":"https://zh.wikisource.org/zh-hans/三國志/卷02"},{"label":"《三国志·吴书·吴主传》","url":"https://zh.wikisource.org/zh-hans/三國志/卷47"},{"label":"鄂州市民政局：鄂州市最古老地名—吴王城","url":"https://mzj.ezhou.gov.cn/ztzl/dmpc/201602/t20160224_208688.html"},{"label":"南京市地方志：东吴政权两次迁都南京","url":"https://dfz.nanjing.gov.cn/gzdt/202403/t20240315_4186987.html"}]','大皇帝','太祖','大皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('yuan-shao','袁绍','han-east','[]',NULL,NULL,154,1,NULL,'year',202,6,NULL,'month','["军阀"]','东汉末军阀，字本初，汝南汝阳人，出身汝南袁氏。董卓乱政后参与关东联军，控制冀、青、并等州；官渡之战败于曹操，202年病逝，袁氏势力随后瓦解。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/袁绍"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhou-yu','周瑜','wu','[]',NULL,NULL,175,1,NULL,'year',210,1,NULL,'year','["军事家"]','东汉末孙吴将领，字公瑾，庐江舒人。辅佐孙策平定江东，孙权时任水军统帅；208年赤壁之战与刘备联军击败曹操军，后筹划攻取益州，病逝于巴丘。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/周瑜"}]',NULL,NULL,NULL,'[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhuge-liang','诸葛亮','shu','[]',NULL,NULL,181,1,NULL,'year',234,8,NULL,'month','["政治家","军事家"]','三国蜀汉政治家、军事家，字孔明，琅邪阳都人。刘备三顾茅庐后出仕，辅佐建立蜀汉并任丞相；刘备死后主持朝政，多次北伐曹魏，卒于五丈原。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/诸葛亮"}]',NULL,NULL,NULL,'[]');
