INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content") VALUES ('guandu','官渡之战','battle','point','month',NULL,NULL,'建安五年六月，曹操大败袁绍',200,6,NULL,2405,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'曹操以少胜多，大败袁绍，奠定统一北方基础。',NULL,NULL);
